// PRINT CUBE bootstrap: recreates the full project (all folders) from one file.
// Render build command: node bundle.mjs && npm install && npm run build
import { gunzipSync } from "node:zlib";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
const DATA = "";
const files = JSON.parse(gunzipSync(Buffer.from(DATA, "base64")).toString());
for (const [p, b64] of Object.entries(files)) {
  if (p.includes("..")) continue;
  mkdirSync(dirname(p) || ".", { recursive: true });
  writeFileSync(p, Buffer.from(b64, "base64"));
}
console.log("Restored " + Object.keys(files).length + " files");
